<script setup lang="ts">
import { Eye, BrokenImage } from './internal/icons';
import { ref, computed, inject, getCurrentInstance, watchEffect, watch } from 'vue';
import type { CSSProperties } from 'vue';
import { imageGroupKey } from './internal/image'; import PreviewLayer from './internal/PreviewLayer.vue';
import './styles/theme.css'; import './styles/image.css';
const props = withDefaults(defineProps<{ src: string; alt?: string; preview?: boolean | { src?: string; mask?: string; visible?: boolean; onVisibleChange?: (value: boolean) => void }; fallback?: string; placeholder?: boolean; fit?: CSSProperties['objectFit']; rounded?: boolean | number; width?: number | string; height?: number | string; loading?: 'lazy' | 'eager' }>(), { alt: '', preview: true, placeholder: true, fit: 'cover', rounded: true, loading: 'lazy' });
const emit = defineEmits<{ previewOpen: []; load: [event: Event]; error: [event: Event]; 'update:visible': [value: boolean] }>(); const id = `image-${getCurrentInstance()?.uid}`; const group = inject(imageGroupKey, null); const config = computed(() => props.preview ? props.preview === true ? {} : props.preview : null); const status = ref('loading'), failed = ref(false), innerOpen = ref(false); const opened = computed(() => config.value?.visible ?? innerOpen.value);
watchEffect(() => { void props.src; status.value = 'loading'; failed.value = false; }); watch([() => props.src, () => config.value?.src, () => !!config.value], (_, __, cleanup) => { if (group && config.value) cleanup(group.register({ id, src: props.src, previewSrc: config.value.src })); }, { immediate: true });
function setOpen(value: boolean) { if (config.value?.visible === undefined) innerOpen.value = value; config.value?.onVisibleChange?.(value); emit('update:visible', value); }
function show() { if (!config.value || failed.value || status.value !== 'loaded') return; emit('previewOpen'); if (group) group.open(id); else setOpen(true); }
function error(event: Event) { emit('error', event); if (props.fallback && !failed.value) { failed.value = true; status.value = 'loading'; } else status.value = 'error'; }
</script>
<template><span :class="['at-image', { 'at-image--previewable': config && status === 'loaded' && !failed, 'at-image--loading': status === 'loading', 'at-image--error': status === 'error', 'at-image--square': rounded === false }]" :style="{ width: typeof width === 'number' ? `${width}px` : width, height: typeof height === 'number' ? `${height}px` : height, borderRadius: typeof rounded === 'number' ? `${rounded}px` : rounded === false ? '0' : undefined }"><span v-if="status === 'loading' && placeholder" class="at-image__placeholder" aria-hidden="true"><slot name="placeholder"><span class="at-image__skeleton" /></slot></span><img :src="failed && fallback ? fallback : src" :alt="alt" :width="width" :height="height" :loading="loading" class="at-image__img" :style="{ objectFit: fit }" @load="status = 'loaded'; emit('load', $event)" @error="error"><span v-if="status === 'error'" class="at-image__broken" role="img" :aria-label="alt || '图片加载失败'"><BrokenImage /></span><button v-if="config && status === 'loaded' && !failed" type="button" class="at-image__mask" :aria-label="`预览${alt ? `：${alt}` : '图片'}`" @click="show"><span class="at-image__mask-content"><slot name="mask"><Eye />{{ config.mask ?? '预览' }}</slot></span></button><PreviewLayer v-if="opened && !group" :items="[{ id, src, previewSrc: config?.src }]" :index="0" @close="setOpen(false)" /></span></template>
